questionvariables.text:
/* Randomise side lengths */
a: rand(5)+6;
b: rand(5)+6;

/* Choose c so that a, b and c form a valid triangle */
c: min(a,b)+rand(min(a,b));

/* Rearrange the cosine rule to calculate cos(C) */
cosC: (a^2+b^2-c^2)/(2*a*b);

/* Calculate the angle in degrees */
C_rad: acos(cosC);
C_deg: float(C_rad*180/%pi);
C_ans: float(C_deg);
